package io.tornado.notification;
import io.tornado.persistence.*;import org.springframework.stereotype.Component;import java.math.*;import java.time.*;import java.time.format.*;
@Component public class TelegramMessageFormatter{private static final ZoneId TEHRAN=ZoneId.of("Asia/Tehran");private static final DateTimeFormatter TIME=DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss 'Tehran'");private String price(BigDecimal p){return String.format(java.util.Locale.US,"%,.4f",p);}private String horizon(long s){return s<3600?s/60+"m":s<86400?s/3600+"h":"24h";}
 public String open(MixTradeSimulation s){String side=s.getDirection()==Direction.UP?"🟢 Direction: LONG":"🔴 Direction: SHORT";return "🚨 TORNIDO SIGNAL\n\n🪙 Coin: "+s.getCoin().getSymbol()+"/USDT\n"+side+"\n⏱ Horizon: "+horizon(s.getHorizonSeconds())+"\n\n🏆 Best Mix: #"+s.getMixRank()+"\n🧠 Methods:\n"+String.join(" + ",s.getMethodNames())+"\n\n🗳 Agreement: "+s.getAgreementCount()+" / "+s.getTotalMethods()+" "+(s.getDirection()==Direction.UP?"LONG":"SHORT")+"\n\n💰 Entry: "+price(s.getEntryPrice())+" USDT\n🎯 Target: "+price(s.getTargetPrice())+" USDT (+0.30%)\n🛑 Stop Loss: "+price(s.getStopLossPrice())+" USDT\n\n📊 Historical Trades: "+s.getHistoricalSamples()+"\n✅ Target Hit Rate: "+String.format("%.1f%%",s.getHistoricalTargetHitRate())+"\n📈 Directional Accuracy: "+String.format("%.1f%%",s.getHistoricalDirectionalAccuracy())+"\n📐 Wilson Score: "+String.format("%.1f%%",s.getHistoricalWilsonScore())+"\n\n🕒 Opened: "+TIME.format(s.getOpenedAt().atZone(TEHRAN))+"\n📌 Simulation ID: #"+s.getId()+"\n\n⏳ Status: OPEN";}
 public String closed(MixTradeSimulation s){String base=open(s);int at=base.lastIndexOf("⏳ Status:");Duration d=Duration.between(s.getOpenedAt(),s.getClosedAt());String title=s.getStatus()==MixTradeSimulation.Status.TARGET_HIT?"✅🎯 TARGET HIT":"❌🛑 STOP LOSS HIT";return base.substring(0,at)+title+"\n\n"+(s.getStatus()==MixTradeSimulation.Status.TARGET_HIT?"✅ Status: TARGET HIT":"❌ Status: STOP LOSS HIT")+"\n💵 Hit Price: "+price(s.getClosePrice())+" USDT\n🕒 Closed: "+TIME.format(s.getClosedAt().atZone(TEHRAN))+"\n⏱ Duration: "+d.toHoursPart()+"h "+d.toMinutesPart()+"m "+d.toSecondsPart()+"s\n"+(s.getResultPercent()>=0?"📈":"📉")+" Result: "+String.format("%+.3f%%",s.getResultPercent());}
}
